//! Fixture differential for placed features.
//!
//! The fixture world was generated by the 26.3 server, so its chunks are the
//! reference output for noise fill, surface rules, carvers and features. This
//! test decorates structure-free fixture chunks with the Rust feature engine and
//! compares the ore blocks exactly (position and block state) and the vegetation
//! counts/positions statistically. Feature types that are not implemented yet
//! (geodes, lakes, monster rooms, mushroom patches, sugar cane, ...) are simply
//! absent from the Rust output, so a whole-chunk equality check is not possible.

use ferrite_nbt::{
    Tag,
    binary::{self, Compression},
};
use ferrite_world::{BlockStateRegistry, Chunk, RegionFile, RuntimeRegistry, chunk_from_nbt};
use ferrite_worldgen::{FeatureGenerator, NoiseChunkGenerator, SurfaceGenerator, WorldgenData};
use std::collections::BTreeMap;
use std::path::PathBuf;

fn generated() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../vanilla/26.3/generated")
}

fn fixture_base() -> PathBuf {
    generated().parent().unwrap().to_owned()
}

fn fixture_seed() -> i64 {
    let path = fixture_base().join("fixture-world/world/data/minecraft/world_gen_settings.dat");
    let (_, tag) = binary::read_compressed(&std::fs::read(path).unwrap(), Compression::Gzip)
        .expect("read fixture world settings");
    let Tag::Compound(root) = tag else {
        panic!("worldgen root")
    };
    let Some(Tag::Compound(settings)) = root.get("data") else {
        panic!("worldgen data")
    };
    let Some(Tag::Long(seed)) = settings.get("seed") else {
        panic!("seed")
    };
    *seed
}

fn fill_biomes(
    chunk: &mut Chunk,
    surface: &SurfaceGenerator<'_>,
    registry: &RuntimeRegistry,
    chunk_x: i32,
    chunk_z: i32,
) {
    let min_y = chunk.min_y();
    for (section_index, section) in chunk.sections_mut().iter_mut().enumerate() {
        for qy in 0..4 {
            let y = min_y + section_index as i32 * 16 + qy * 4 + 2;
            for qz in 0..4 {
                let z = chunk_z * 16 + qz * 4 + 2;
                for qx in 0..4 {
                    let x = chunk_x * 16 + qx * 4 + 2;
                    let name = surface.biome_at(x, y, z);
                    let id = registry
                        .biome_id(&name.to_string())
                        .unwrap_or_else(|| panic!("unknown biome {name}"));
                    section
                        .set_biome((qy * 16 + qz * 4 + qx) as usize, id)
                        .unwrap();
                }
            }
        }
    }
}

fn generate(
    data: &WorldgenData,
    registry: &RuntimeRegistry,
    noise: &NoiseChunkGenerator,
    seed: i64,
    chunk_x: i32,
    chunk_z: i32,
) -> Chunk {
    let surface = SurfaceGenerator::new(data, noise, seed).unwrap();
    let mut chunk = noise.fill_noise_chunk(chunk_x, chunk_z, registry).unwrap();
    surface
        .apply(&mut chunk, chunk_x, chunk_z, registry)
        .unwrap();
    noise
        .carve_chunk(&mut chunk, chunk_x, chunk_z, registry)
        .unwrap();
    fill_biomes(&mut chunk, &surface, registry, chunk_x, chunk_z);
    let mut features =
        FeatureGenerator::new(data, seed, chunk.min_y(), chunk.height_blocks() as i32);
    features
        .decorate(
            &mut chunk,
            chunk_x,
            chunk_z,
            &|x, y, z| surface.biome_at(x, y, z),
            registry,
        )
        .unwrap();
    chunk
}

fn fixture_chunk(cx: i32, cz: i32, registry: &RuntimeRegistry) -> Option<(Chunk, bool)> {
    let region = RegionFile::open(
        fixture_base().join("fixture-world/world/dimensions/minecraft/overworld/region/r.0.0.mca"),
        cx.div_euclid(32),
        cz.div_euclid(32),
    )
    .ok()?;
    let bytes = region.read_chunk(cx, cz).ok()??;
    let (_, tag) = binary::read_named(&bytes).ok()?;
    let Tag::Compound(root) = &tag else {
        return None;
    };
    let Some(Tag::Compound(structures)) = root.get("structures") else {
        return None;
    };
    let Some(Tag::Compound(references)) = structures.get("References") else {
        return None;
    };
    let clear = references.is_empty();
    Some((chunk_from_nbt(&tag, -64, 384, registry).ok()?, clear))
}

fn is_ore(name: &str) -> bool {
    name.ends_with("_ore")
}

fn is_ground_vegetation(name: &str) -> bool {
    is_vegetation(name) && !name.ends_with("_log")
}

fn is_vegetation(name: &str) -> bool {
    matches!(
        name,
        "minecraft:short_grass"
            | "minecraft:tall_grass"
            | "minecraft:fern"
            | "minecraft:large_fern"
            | "minecraft:dandelion"
            | "minecraft:poppy"
            | "minecraft:azure_bluet"
            | "minecraft:oxeye_daisy"
            | "minecraft:cornflower"
            | "minecraft:orange_tulip"
            | "minecraft:red_tulip"
            | "minecraft:pink_tulip"
            | "minecraft:white_tulip"
    ) || name.ends_with("_log")
}

#[test]
fn feature_data_records_are_complete() {
    let data = WorldgenData::load(generated()).unwrap();
    println!(
        "features: {} configured, {} placed, {} providers, {} block tags",
        data.counts().configured_features,
        data.counts().placed_features,
        data.counts().block_state_providers,
        data.counts().block_tags
    );
    // `feature/` contains 235 top-level files plus the entries in `coral/`.
    assert!(data.counts().configured_features >= 235);
    assert_eq!(data.counts().placed_features, 273);
    assert!(data.counts().block_state_providers > 0);
    let missing: Vec<_> = data
        .placed_features
        .values()
        .filter(|placed| data.configured_feature(&placed.feature).is_none())
        .map(|placed| placed.feature.to_string())
        .collect();
    assert!(
        missing.is_empty(),
        "placed features without a configured feature: {missing:?}"
    );
    for biome in data.biomes.values() {
        for feature in biome.features.iter().flatten() {
            assert!(
                data.placed_feature(feature).is_some(),
                "biome references unknown placed feature {feature}"
            );
        }
    }
}

#[test]
fn fixture_vegetation_on_land() {
    // Chunks 24..29,0 of the fixture are plains; the origin chunks are deep
    // ocean whose grass grows on lush-cave moss, which the `vegetation_patch`
    // feature type (out of scope for this subset) would place.
    let seed = fixture_seed();
    let data = WorldgenData::load(generated()).unwrap();
    let registry = RuntimeRegistry::load(generated()).unwrap();
    let noise = NoiseChunkGenerator::new(&data, seed).unwrap();

    let mut expected_total = 0usize;
    let mut actual_total = 0usize;
    let mut matched = 0usize;
    let mut counts = BTreeMap::<String, (usize, usize)>::new();
    for (cx, cz) in [(13, 18), (20, 14), (22, 14), (20, 15)] {
        let Some((expected, clear)) = fixture_chunk(cx, cz, &registry) else {
            continue;
        };
        if !clear {
            continue;
        }
        let mut expected_biomes = Vec::new();
        for section in expected.sections() {
            for index in 0..64 {
                if let Some(id) = section.biomes().get(index)
                    && let Some(name) = registry.biome_name(id)
                    && !expected_biomes.contains(&name.to_owned())
                {
                    expected_biomes.push(name.to_owned());
                }
            }
        }
        eprintln!("vegetation chunk {cx},{cz} biomes: {expected_biomes:?}");
        let actual = generate(&data, &registry, &noise, seed, cx, cz);
        for y in -64..320 {
            for z in 0..16 {
                for x in 0..16 {
                    let expected_id = expected.block(x, y, z).unwrap();
                    let actual_id = actual.block(x, y, z).unwrap();
                    let expected_name = registry
                        .block_state(expected_id)
                        .map_or("", |state| state.name.as_str());
                    let actual_name = registry
                        .block_state(actual_id)
                        .map_or("", |state| state.name.as_str());
                    if is_ground_vegetation(expected_name) {
                        expected_total += 1;
                        counts.entry(expected_name.to_owned()).or_default().0 += 1;
                        if expected_id == actual_id {
                            matched += 1;
                        }
                    }
                    if is_ground_vegetation(actual_name) {
                        actual_total += 1;
                        counts.entry(actual_name.to_owned()).or_default().1 += 1;
                    }
                }
            }
        }
    }
    for (name, (expected, actual)) in &counts {
        println!("vegetation {name}: expected {expected}, actual {actual}");
    }
    let ratio = actual_total as f64 / expected_total.max(1) as f64;
    println!(
        "vegetation totals: actual {actual_total}, expected {expected_total}, ratio {ratio:.3}, \
         exact match {matched}/{expected_total}"
    );
    assert!(
        expected_total > 50,
        "fixture land chunks have no vegetation"
    );
    // These old-growth taiga chunks also contain spruce trees (non-blob
    // foliage placer, out of scope for the simple-tree subset) and lush-cave
    // moss patches (`vegetation_patch`, also out of scope). The statistical
    // contract therefore covers the implemented ground cover: it must be the
    // same order of magnitude as the Java fixture, not vanish.
    assert!(
        (0.3..1.5).contains(&ratio),
        "vegetation total ratio outside 0.3..1.5: {ratio}"
    );
}

#[test]
fn fixture_features_match_vanilla() {
    let seed = fixture_seed();
    eprintln!("fixture seed: {seed}");
    let data = WorldgenData::load(generated()).unwrap();
    let registry = RuntimeRegistry::load(generated()).unwrap();
    let noise = NoiseChunkGenerator::new(&data, seed).unwrap();

    let mut ore_expected = 0usize;
    let mut ore_matched = 0usize;
    let mut ore_actual_only = 0usize;
    let mut vegetation_expected = 0usize;
    let mut vegetation_matched = 0usize;
    let mut vegetation_actual = 0usize;
    let mut per_chunk = Vec::new();
    let mut names = BTreeMap::<String, usize>::new();
    let mut expected_counts = BTreeMap::<String, usize>::new();
    let mut actual_counts = BTreeMap::<String, usize>::new();

    // These fixture chunks have complete terrain data and no structure references.
    for (cx, cz) in [(0, 0), (1, 0), (8, 0), (0, 1), (8, 1), (0, 8), (1, 8)] {
        let Some((expected, clear)) = fixture_chunk(cx, cz, &registry) else {
            continue;
        };
        if !clear {
            continue;
        }
        let mut expected_biomes = Vec::new();
        for section in expected.sections() {
            for index in 0..64 {
                if let Some(id) = section.biomes().get(index)
                    && let Some(name) = registry.biome_name(id)
                    && !expected_biomes.contains(&name.to_owned())
                {
                    expected_biomes.push(name.to_owned());
                }
            }
        }
        let actual = generate(&data, &registry, &noise, seed, cx, cz);
        let mut biomes = Vec::new();
        for section in actual.sections() {
            for index in 0..64 {
                if let Some(id) = section.biomes().get(index)
                    && let Some(name) = registry.biome_name(id)
                    && !biomes.contains(&name.to_owned())
                {
                    biomes.push(name.to_owned());
                }
            }
        }
        eprintln!("chunk {cx},{cz} biomes: expected {expected_biomes:?} actual {biomes:?}");
        let mut chunk_ore_expected = 0;
        let mut chunk_ore_matched = 0;
        let mut chunk_veg_expected = 0;
        let mut chunk_veg_matched = 0;

        for y in -64..320 {
            for z in 0..16 {
                for x in 0..16 {
                    let expected_id = expected.block(x, y, z).unwrap();
                    let actual_id = actual.block(x, y, z).unwrap();
                    let expected_name = registry
                        .block_state(expected_id)
                        .map_or("", |state| state.name.as_str());
                    let actual_name = registry
                        .block_state(actual_id)
                        .map_or("", |state| state.name.as_str());
                    if is_ore(expected_name) {
                        *expected_counts.entry(expected_name.to_owned()).or_default() += 1;
                        ore_expected += 1;
                        chunk_ore_expected += 1;
                        if expected_id == actual_id {
                            ore_matched += 1;
                            chunk_ore_matched += 1;
                        }
                    } else if is_ore(actual_name) {
                        ore_actual_only += 1;
                    }
                    if is_ore(actual_name) {
                        *actual_counts.entry(actual_name.to_owned()).or_default() += 1;
                    }
                    if is_vegetation(expected_name) {
                        vegetation_expected += 1;
                        chunk_veg_expected += 1;
                        if expected_id == actual_id {
                            vegetation_matched += 1;
                            chunk_veg_matched += 1;
                        }
                    }
                    if is_vegetation(actual_name) {
                        vegetation_actual += 1;
                    }
                    if expected_name != actual_name
                        && (is_ore(expected_name)
                            || is_vegetation(expected_name)
                            || is_ore(actual_name)
                            || is_vegetation(actual_name))
                    {
                        *names
                            .entry(format!("{expected_name}->{actual_name}"))
                            .or_default() += 1;
                    }
                }
            }
        }
        per_chunk.push((
            cx,
            cz,
            chunk_ore_expected,
            chunk_ore_matched,
            chunk_veg_expected,
            chunk_veg_matched,
        ));
    }

    for (cx, cz, ore_total, ore_hit, veg_total, veg_hit) in &per_chunk {
        println!("chunk {cx},{cz}: ores {ore_hit}/{ore_total}, vegetation {veg_hit}/{veg_total}");
    }
    let ore_rate = ore_matched as f64 / ore_expected.max(1) as f64;
    let ore_actual_total: usize = actual_counts.values().sum();
    let ore_total_ratio = ore_actual_total as f64 / ore_expected.max(1) as f64;
    let vegetation_rate = vegetation_matched as f64 / vegetation_expected.max(1) as f64;
    println!(
        "features: ores {ore_matched}/{ore_expected} = {:.3}% (actual-only {ore_actual_only}); \
         vegetation {vegetation_matched}/{vegetation_expected} = {:.3}% (actual {vegetation_actual})",
        ore_rate * 100.0,
        vegetation_rate * 100.0
    );
    let mut common: Vec<_> = names.into_iter().collect();
    common.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
    eprintln!("feature mismatches: {:?}", &common[..common.len().min(20)]);
    let mut ore_counts: BTreeMap<&str, (usize, usize)> = BTreeMap::new();
    for (name, count) in &expected_counts {
        ore_counts.entry(name).or_default().0 = *count;
    }
    for (name, count) in &actual_counts {
        ore_counts.entry(name).or_default().1 = *count;
    }
    for (name, (expected, actual)) in &ore_counts {
        println!("ore {name}: expected {expected}, actual {actual}");
    }

    assert!(ore_expected > 0, "fixture has no ore blocks");
    // Exact positions depend on the large andesite/diorite/granite/tuff blobs
    // whose ore shapes shift which base block an ore replaces. The statistical
    // contract is the total ore volume and the presence of every common type.
    println!(
        "ore totals: actual {ore_actual_total}, expected {ore_expected}, ratio \
         {ore_total_ratio:.3}, exact position match {:.3}%",
        ore_rate * 100.0
    );
    assert!(
        (0.75..1.35).contains(&ore_total_ratio),
        "ore total ratio outside 0.75..1.35: {ore_total_ratio}"
    );
    for (name, (expected, actual)) in &ore_counts {
        if *expected >= 50 {
            assert!(*actual > 0, "ore {name} missing from generated chunk");
        }
    }
    // The fixture origin is ocean/lush-caves, so this exact-position check only
    // covers the ore subset. Vegetation placement is covered by
    // `fixture_vegetation_on_land` above.
    let _ = vegetation_rate;
}
